/**
 * Disjoint sets over the elements `0 .. count - 1`, joined by size and undone
 * in reverse order.
 *
 * Every union is recorded, so `undo` and `rollback` restore exactly the state
 * that existed before it: the same roots, the same component sizes, and the
 * same answer from `find` for every element.
 */
export class DisjointSets {
  #parent;
  #size;
  /** @type {Array<{attached: number, root: number}>} */
  #log = [];
  #components;

  /**
   * @param {number} count How many elements the structure holds.
   * @throws {TypeError} When the count is not a non-negative safe integer.
   */
  constructor(count) {
    if (!Number.isSafeInteger(count) || count < 0) throw new TypeError('count must be a non-negative integer');
    this.#parent = Array.from({ length: count }, (_, index) => index);
    this.#size = new Array(count).fill(1);
    this.#components = count;
  }

  /** @returns {number} How many elements the structure holds. */
  get count() {
    return this.#parent.length;
  }

  /** @returns {number} How many disjoint sets exist right now. */
  get components() {
    return this.#components;
  }

  /**
   * Validates an element index.
   * @param {unknown} element Candidate element.
   * @returns {number} The element itself.
   * @throws {RangeError} When the element is outside `0 .. count - 1`.
   */
  #check(element) {
    if (!Number.isSafeInteger(element) || element < 0 || element >= this.#parent.length) {
      throw new RangeError(`element out of range: ${String(element)}`);
    }
    return element;
  }

  /**
   * Finds the representative of an element's set.
   * @param {number} element Element to look up.
   * @returns {number} Root element of the set.
   * @throws {RangeError} When the element is outside the structure.
   */
  find(element) {
    let node = this.#check(element);
    while (this.#parent[node] !== node) node = this.#parent[node];
    return node;
  }

  /**
   * Reports whether two elements share a set.
   * @param {number} a First element.
   * @param {number} b Second element.
   * @returns {boolean} True when both share a representative.
   */
  connected(a, b) {
    return this.find(a) === this.find(b);
  }

  /**
   * Reports how many elements share an element's set.
   * @param {number} element Element to measure.
   * @returns {number} Size of the set.
   */
  sizeOf(element) {
    return this.#size[this.find(element)];
  }

  /**
   * Joins two sets, attaching the smaller under the larger and, on a tie, the
   * larger root index under the smaller.
   * @param {number} a First element.
   * @param {number} b Second element.
   * @returns {boolean} False when both elements already shared a set.
   */
  union(a, b) {
    const rootA = this.find(a);
    const rootB = this.find(b);
    if (rootA === rootB) return false;
    let root = rootA;
    let attached = rootB;
    if (this.#size[rootB] > this.#size[rootA] || (this.#size[rootB] === this.#size[rootA] && rootB < rootA)) {
      root = rootB;
      attached = rootA;
    }
    this.#parent[attached] = root;
    this.#size[root] += this.#size[attached];
    this.#log.push({ attached, root });
    this.#components -= 1;
    return true;
  }

  /**
   * Marks the current state so it can be restored later.
   * @returns {number} Token naming this state.
   */
  checkpoint() {
    return this.#log.length;
  }

  /**
   * Undoes the most recent union.
   * @returns {boolean} False when no union was left to undo.
   */
  undo() {
    const last = this.#log.pop();
    if (last === undefined) return false;
    this.#size[last.root] -= this.#size[last.attached];
    this.#parent[last.attached] = last.attached;
    this.#components += 1;
    return true;
  }

  /**
   * Undoes unions until the state matches a checkpoint.
   * @param {number} token Token from `checkpoint`.
   * @returns {number} How many unions were undone.
   * @throws {RangeError} When the token does not name a reachable state.
   */
  rollback(token) {
    if (!Number.isSafeInteger(token) || token < 0 || token > this.#log.length) {
      throw new RangeError(`unknown checkpoint: ${String(token)}`);
    }
    let undone = 0;
    while (this.#log.length > token) {
      this.undo();
      undone += 1;
    }
    return undone;
  }

  /**
   * Lists the sets, each sorted ascending, ordered by their smallest member.
   * @returns {number[][]} Current partition.
   */
  groups() {
    /** @type {Map<number, number[]>} */
    const byRoot = new Map();
    for (let element = 0; element < this.#parent.length; element += 1) {
      const root = this.find(element);
      const members = byRoot.get(root);
      if (members === undefined) byRoot.set(root, [element]);
      else members.push(element);
    }
    return [...byRoot.values()].sort((a, b) => a[0] - b[0]);
  }
}

import { DisjointSets } from './dsu.js';

/**
 * Spanning-forest and what-if queries built on the rollback-capable
 * disjoint-set structure.
 *
 * An edge is `[u, v, weight]` with element indices and a finite weight.
 */

/**
 * Validates an edge list against an element count.
 * @param {unknown} edges Candidate edge list.
 * @param {number} count Element count the edges index into.
 * @returns {Array<[number, number, number]>} Copies of the validated edges.
 * @throws {TypeError} When the list or an edge is malformed.
 * @throws {RangeError} When an endpoint is outside the structure.
 */
function checkEdges(edges, count) {
  if (!Array.isArray(edges)) throw new TypeError('edges must be an array');
  return edges.map((edge) => {
    if (!Array.isArray(edge) || edge.length !== 3) throw new TypeError('edge must be [u, v, weight]');
    const [u, v, weight] = edge;
    for (const endpoint of [u, v]) {
      if (!Number.isSafeInteger(endpoint) || endpoint < 0 || endpoint >= count) {
        throw new RangeError(`element out of range: ${String(endpoint)}`);
      }
    }
    if (typeof weight !== 'number' || !Number.isFinite(weight)) throw new TypeError('weight must be a finite number');
    return [u, v, weight];
  });
}

/**
 * Builds a minimum spanning forest with Kruskal's algorithm, taking edges by
 * weight and breaking ties by the first endpoint and then the second.
 * @param {number} count Element count.
 * @param {unknown} edges Available edges.
 * @returns {{edges: Array<[number, number, number]>, weight: number, components: number}} Chosen edges, their total weight, and the remaining component count.
 */
export function minimumSpanningForest(count, edges) {
  const sets = new DisjointSets(count);
  const candidates = checkEdges(edges, count);
  candidates.sort((a, b) => a[2] - b[2] || a[0] - b[0] || a[1] - b[1]);
  const chosen = [];
  let weight = 0;
  for (const edge of candidates) {
    if (sets.union(edge[0], edge[1])) {
      chosen.push(edge);
      weight += edge[2];
    }
  }
  return { edges: chosen, weight, components: sets.components };
}

/**
 * Measures how many components remain after each alternative edge set is
 * added on top of a shared base, evaluating each alternative independently by
 * rolling back to the state the base left behind.
 * @param {number} count Element count.
 * @param {unknown} baseEdges Edges applied once, before any alternative.
 * @param {unknown} alternatives Array of edge lists to try one at a time.
 * @returns {{base: number, alternatives: number[]}} Component count for the base and for each alternative.
 * @throws {TypeError} When the alternatives are not an array of edge lists.
 */
export function componentsWithAlternatives(count, baseEdges, alternatives) {
  const sets = new DisjointSets(count);
  for (const [u, v] of checkEdges(baseEdges, count)) sets.union(u, v);
  if (!Array.isArray(alternatives)) throw new TypeError('alternatives must be an array');
  const mark = sets.checkpoint();
  const base = sets.components;
  const results = [];
  for (const alternative of alternatives) {
    for (const [u, v] of checkEdges(alternative, count)) sets.union(u, v);
    results.push(sets.components);
    sets.rollback(mark);
  }
  return { base, alternatives: results };
}

import { test } from 'node:test';
import assert from 'node:assert/strict';

import { DisjointSets } from '../src/dsu.js';

/**
 * Deterministic 32-bit PRNG.
 * @param {number} seed Initial state.
 * @returns {() => number} Generator returning floats in [0, 1).
 */
function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Groups elements by their model label.
 * @param {number[]} labels One label per element.
 * @returns {number[][]} Sets, each ascending, ordered by smallest member.
 */
function groupsOf(labels) {
  const byLabel = new Map();
  labels.forEach((label, element) => {
    if (!byLabel.has(label)) byLabel.set(label, []);
    byLabel.get(label).push(element);
  });
  return [...byLabel.values()].sort((a, b) => a[0] - b[0]);
}

test('a fresh structure holds singletons', () => {
  const sets = new DisjointSets(4);
  assert.deepEqual([sets.count, sets.components], [4, 4]);
  assert.deepEqual(sets.groups(), [[0], [1], [2], [3]]);
  assert.deepEqual([sets.find(2), sets.sizeOf(2), sets.connected(0, 1)], [2, 1, false]);
  assert.deepEqual([new DisjointSets(0).count, new DisjointSets(0).groups()], [0, []]);
  assert.equal(sets.undo(), false);
  assert.equal(sets.rollback(sets.checkpoint()), 0);
});

test('union joins by size and breaks ties with the smaller root', () => {
  const even = new DisjointSets(4);
  assert.equal(even.union(0, 1), true);
  assert.equal(even.union(1, 0), false);
  even.union(2, 3);
  assert.deepEqual([even.find(1), even.find(3), even.components], [0, 2, 2]);
  assert.equal(even.union(1, 3), true);
  assert.deepEqual([even.find(2), even.find(3), even.sizeOf(0), even.components], [0, 0, 4, 1]);
  const uneven = new DisjointSets(5);
  uneven.union(0, 1);
  uneven.union(2, 3);
  uneven.union(2, 4);
  assert.deepEqual([uneven.find(4), uneven.sizeOf(3)], [2, 3]);
  uneven.union(0, 4);
  assert.deepEqual([uneven.find(0), uneven.find(1), uneven.sizeOf(1), uneven.components], [2, 2, 5, 1]);
  assert.deepEqual(uneven.groups(), [[0, 1, 2, 3, 4]]);
});

test('undo reverses one union at a time', () => {
  const sets = new DisjointSets(4);
  sets.union(0, 1);
  sets.union(2, 3);
  sets.union(0, 2);
  assert.deepEqual([sets.components, sets.groups()], [1, [[0, 1, 2, 3]]]);
  assert.equal(sets.undo(), true);
  assert.deepEqual([sets.components, sets.groups(), sets.sizeOf(0), sets.find(3)], [2, [[0, 1], [2, 3]], 2, 2]);
  assert.equal(sets.undo(), true);
  assert.equal(sets.undo(), true);
  assert.deepEqual([sets.components, sets.groups(), sets.find(1)], [4, [[0], [1], [2], [3]], 1]);
  assert.equal(sets.undo(), false);
});

test('rollback returns to a checkpoint and refuses tokens it has passed', () => {
  const sets = new DisjointSets(6);
  sets.union(0, 1);
  const first = sets.checkpoint();
  sets.union(2, 3);
  const second = sets.checkpoint();
  sets.union(4, 5);
  sets.union(0, 2);
  assert.equal(sets.components, 2);
  assert.equal(sets.rollback(second), 2);
  assert.deepEqual([sets.components, sets.groups()], [4, [[0, 1], [2, 3], [4], [5]]]);
  assert.equal(sets.rollback(second), 0);
  assert.equal(sets.rollback(first), 1);
  assert.deepEqual([sets.components, sets.groups()], [5, [[0, 1], [2], [3], [4], [5]]]);
  assert.throws(() => sets.rollback(second), { name: 'RangeError', message: 'unknown checkpoint: 2' });
  assert.throws(() => sets.rollback(-1), { name: 'RangeError', message: 'unknown checkpoint: -1' });
  sets.union(3, 4);
  assert.deepEqual([sets.components, sets.rollback(0), sets.components], [4, 2, 6]);
});

test('rejects malformed counts and elements', () => {
  const sets = new DisjointSets(3);
  const bad = [
    [() => new DisjointSets(-1), 'TypeError', 'count must be a non-negative integer'],
    [() => new DisjointSets(2.5), 'TypeError', 'count must be a non-negative integer'],
    [() => new DisjointSets('3'), 'TypeError', 'count must be a non-negative integer'],
    [() => sets.find(3), 'RangeError', 'element out of range: 3'],
    [() => sets.find(-1), 'RangeError', 'element out of range: -1'],
    [() => sets.union(0, 9), 'RangeError', 'element out of range: 9'],
    [() => sets.sizeOf(1.5), 'RangeError', 'element out of range: 1.5'],
    [() => sets.connected(0, '1'), 'RangeError', 'element out of range: 1'],
    [() => sets.rollback(1.5), 'RangeError', 'unknown checkpoint: 1.5'],
  ];
  for (const [call, name, message] of bad) assert.throws(call, { name, message }, message);
});

test('matches a snapshot model across random unions, checkpoints, and rollbacks', () => {
  const rnd = mulberry32(0x0f5e7);
  const size = 12;
  const sets = new DisjointSets(size);
  let labels = Array.from({ length: size }, (_, index) => index);
  /** @type {number[][]} */
  const history = [labels.slice()];
  /** @type {number[]} */
  const marks = [];
  let unions = 0;

  for (let step = 0; step < 4000; step += 1) {
    const roll = rnd();
    if (roll < 0.5) {
      const a = Math.floor(rnd() * size);
      const b = Math.floor(rnd() * size);
      const joined = labels[a] !== labels[b];
      assert.equal(sets.union(a, b), joined, `union ${a},${b} at step ${step}`);
      if (joined) {
        const from = labels[b];
        const to = labels[a];
        labels = labels.map((label) => (label === from ? to : label));
        unions += 1;
        history[unions] = labels.slice();
      }
    } else if (roll < 0.65) {
      const token = sets.checkpoint();
      assert.equal(token, unions, `checkpoint at step ${step}`);
      marks.push(token);
    } else if (roll < 0.8 && marks.length > 0) {
      const token = marks[Math.floor(rnd() * marks.length)];
      assert.equal(sets.rollback(token), unions - token, `rollback to ${token} at step ${step}`);
      while (marks.length > 0 && marks[marks.length - 1] > token) marks.pop();
      unions = token;
      labels = history[unions].slice();
    } else if (roll < 0.9) {
      const undone = sets.undo();
      assert.equal(undone, unions > 0, `undo at step ${step}`);
      if (undone) {
        unions -= 1;
        labels = history[unions].slice();
        while (marks.length > 0 && marks[marks.length - 1] > unions) marks.pop();
      }
    } else {
      const a = Math.floor(rnd() * size);
      const b = Math.floor(rnd() * size);
      const same = labels[a] === labels[b];
      assert.deepEqual(
        [sets.connected(a, b), sets.find(a) === sets.find(b), sets.sizeOf(a)],
        [same, same, labels.filter((label) => label === labels[a]).length],
        `probe ${a},${b} at step ${step}`,
      );
    }
    const expected = groupsOf(labels);
    assert.deepEqual([sets.components, sets.groups()], [expected.length, expected], `state at step ${step}`);
    assert.ok(expected.some((group) => group.includes(sets.find(0))), `root of 0 at step ${step}`);
  }
  assert.ok(unions > 0, 'expected the sequence to leave unions in place');
});

