test('idle time never fills a bucket past its capacity', () => {
  const { limiter, advance } = harness({ capacity: 3, refillTokens: 1, refillIntervalMs: 100 });
  limiter.tryConsume('a');
  advance(1000000);
  assert.equal(limiter.remaining('a'), 3);
