/**
 * Fixed-size bit set backed by 32-bit words.
 *
 * Bits are numbered from zero. The byte form is portable: byte `b` carries
 * bits `8b` to `8b + 7`, with bit `8b + k` at value `1 << k`, and any bits
 * past the declared size are zero.
 */
export class BitSet {
  #nbits;
  #words;

  /**
   * @param {number} nbits How many bits the set holds; a positive safe integer.
   * @throws {TypeError} When the size is not a positive safe integer.
   */
  constructor(nbits) {
    if (!Number.isSafeInteger(nbits) || nbits <= 0) throw new TypeError('size must be a positive integer');
    this.#nbits = nbits;
    this.#words = new Uint32Array(Math.ceil(nbits / 32));
  }

  /** @returns {number} How many bits the set holds. */
  get size() {
    return this.#nbits;
  }

  /**
   * Validates a bit index.
   * @param {unknown} index Candidate index.
   * @returns {number} The index itself.
   * @throws {RangeError} When the index is outside `0 .. size - 1`.
   */
  #check(index) {
    if (!Number.isSafeInteger(index) || index < 0 || index >= this.#nbits) {
      throw new RangeError(`bit index out of range: ${String(index)}`);
    }
    return index;
  }

  /**
   * Turns a bit on.
   * @param {number} index Bit to set.
   * @returns {BitSet} This set.
   */
  set(index) {
    this.#check(index);
    this.#words[index >>> 5] |= 1 << (index & 31);
    return this;
  }

  /**
   * Turns a bit off.
   * @param {number} index Bit to clear.
   * @returns {BitSet} This set.
   */
  clear(index) {
    this.#check(index);
    this.#words[index >>> 5] &= ~(1 << (index & 31));
    return this;
  }

  /**
   * Flips a bit.
   * @param {number} index Bit to flip.
   * @returns {BitSet} This set.
   */
  toggle(index) {
    this.#check(index);
    this.#words[index >>> 5] ^= 1 << (index & 31);
    return this;
  }

  /**
   * Reads a bit.
   * @param {number} index Bit to read.
   * @returns {boolean} True when the bit is on.
   */
  get(index) {
    this.#check(index);
    return (this.#words[index >>> 5] & (1 << (index & 31))) !== 0;
  }

  /**
   * Counts the bits that are on.
   * @returns {number} Population count.
   */
  count() {
    let total = 0;
    for (const word of this.#words) total += popcount(word);
    return total;
  }

  /**
   * Reports whether another set holds the same size and bits.
   * @param {BitSet} other Set to compare with.
   * @returns {boolean} True when both are equal.
   */
  equals(other) {
    checkSet(other);
    if (other.size !== this.#nbits) return false;
    const words = other.words();
    for (let index = 0; index < this.#words.length; index += 1) {
      if (this.#words[index] !== words[index]) return false;
    }
    return true;
  }

  /**
   * Exposes the backing words so sets can combine without copying bit by bit.
   * @returns {Uint32Array} The backing words.
   */
  words() {
    return this.#words;
  }

  /**
   * Builds the union of two sets of the same size.
   * @param {BitSet} other Set to combine with.
   * @returns {BitSet} New set holding every bit of either input.
   * @throws {RangeError} When the sizes differ.
   */
  or(other) {
    const result = this.#combined(other);
    const words = other.words();
    for (let index = 0; index < this.#words.length; index += 1) {
      result.words()[index] = this.#words[index] | words[index];
    }
    return result;
  }

  /**
   * Builds the intersection of two sets of the same size.
   * @param {BitSet} other Set to combine with.
   * @returns {BitSet} New set holding the bits present in both inputs.
   * @throws {RangeError} When the sizes differ.
   */
  and(other) {
    const result = this.#combined(other);
    const words = other.words();
    for (let index = 0; index < this.#words.length; index += 1) {
      result.words()[index] = this.#words[index] & words[index];
    }
    return result;
  }

  /**
   * Checks that two sets can be combined and allocates the result.
   * @param {BitSet} other Set to combine with.
   * @returns {BitSet} Empty set of the shared size.
   * @throws {RangeError} When the sizes differ.
   */
  #combined(other) {
    checkSet(other);
    if (other.size !== this.#nbits) throw new RangeError('bit sets must have the same size');
    return new BitSet(this.#nbits);
  }

  /**
   * Copies the bits into bytes.
   * @returns {Uint8Array} `ceil(size / 8)` bytes, least significant bit first.
   */
  toBytes() {
    const bytes = new Uint8Array(byteLength(this.#nbits));
    for (let index = 0; index < this.#nbits; index += 1) {
      if (this.get(index)) bytes[index >>> 3] |= 1 << (index & 7);
    }
    return bytes;
  }

  /**
   * Rebuilds a set from bytes.
   * @param {Uint8Array} bytes Bytes from `toBytes`.
   * @param {number} nbits Size the bytes describe.
   * @returns {BitSet} Restored set.
   * @throws {TypeError} When the bytes are not a Uint8Array.
   * @throws {RangeError} When the byte count or the padding bits are wrong.
   */
  static fromBytes(bytes, nbits) {
    if (!(bytes instanceof Uint8Array)) throw new TypeError('bytes must be a Uint8Array');
    const set = new BitSet(nbits);
    if (bytes.length !== byteLength(nbits)) throw new RangeError('byte length does not match bit size');
    for (let index = 0; index < nbits; index += 1) {
      if ((bytes[index >>> 3] & (1 << (index & 7))) !== 0) set.set(index);
    }
    const spare = byteLength(nbits) * 8 - nbits;
    if (spare > 0 && (bytes[bytes.length - 1] >>> (8 - spare)) !== 0) {
      throw new RangeError('bytes hold bits beyond the set size');
    }
    return set;
  }
}

/**
 * Bytes needed to carry a number of bits.
 * @param {number} nbits Bit count.
 * @returns {number} Byte count.
 */
export function byteLength(nbits) {
  return Math.ceil(nbits / 8);
}

/**
 * Counts the bits set in one 32-bit word.
 * @param {number} word Word to count.
 * @returns {number} Population count, including bit 31.
 */
function popcount(word) {
  let value = word - ((word >>> 1) & 0x55555555);
  value = (value & 0x33333333) + ((value >>> 2) & 0x33333333);
  value = (value + (value >>> 4)) & 0x0f0f0f0f;
  return Math.imul(value, 0x01010101) >>> 24;
}

/**
 * Validates that a value is a bit set.
 * @param {unknown} value Candidate set.
 * @returns {void}
 * @throws {TypeError} When the value is not a BitSet.
 */
function checkSet(value) {
  if (!(value instanceof BitSet)) throw new TypeError('argument must be a BitSet');
}

import { BitSet, byteLength } from './bitset.js';

/**
 * Bloom filter over strings, using double hashing.
 *
 * Two 32-bit FNV-1a hashes are derived from the value and the seed; probe `i`
 * lands on `(h1 + i * h2) mod bits`, computed unsigned so a probe is always a
 * valid bit index. A filter answers `has` with no false negatives; a `true`
 * answer may be a false positive.
 */

/** File signature written at the start of a serialized filter: "BLM1". */
const MAGIC = [0x42, 0x4c, 0x4d, 0x31];
/** Bytes of header before the bit payload. */
const HEADER_BYTES = 17;
/** FNV-1a 32-bit offset basis. */
const FNV_OFFSET = 0x811c9dc5;
/** FNV-1a 32-bit prime. */
const FNV_PRIME = 0x01000193;
/** Constant mixed into the seed for the second hash. */
const SECOND_SEED = 0x9e3779b9;

/**
 * FNV-1a over the UTF-16 code units of a string.
 * @param {string} value Value to hash.
 * @param {number} seed Starting seed.
 * @returns {number} Unsigned 32-bit hash.
 */
function fnv1a(value, seed) {
  let hash = (FNV_OFFSET ^ seed) >>> 0;
  for (let index = 0; index < value.length; index += 1) {
    hash = (hash ^ value.charCodeAt(index)) >>> 0;
    hash = Math.imul(hash, FNV_PRIME) >>> 0;
  }
  return hash >>> 0;
}

/** Bloom filter with a fixed bit count and probe count. */
export class BloomFilter {
  #bits;
  #hashes;
  #seed;
  #set;
  #count = 0;

  /**
   * @param {object} options Filter options.
   * @param {number} options.bits Bit count; a positive safe integer.
   * @param {number} options.hashes Probes per value; a positive safe integer.
   * @param {number} [options.seed] Hash seed; an unsigned 32-bit integer, zero by default.
   */
  constructor(options) {
    if (typeof options !== 'object' || options === null) throw new TypeError('options must be an object');
    const { bits, hashes, seed = 0 } = options;
    if (!Number.isSafeInteger(bits) || bits <= 0) throw new TypeError('bits must be a positive integer');
    if (!Number.isSafeInteger(hashes) || hashes <= 0) throw new TypeError('hashes must be a positive integer');
    if (!Number.isSafeInteger(seed) || seed < 0 || seed > 0xffffffff) {
      throw new TypeError('seed must be a 32-bit unsigned integer');
    }
    this.#bits = bits;
    this.#hashes = hashes;
    this.#seed = seed;
    this.#set = new BitSet(bits);
  }

  /** @returns {number} Bit count. */
  get bits() {
    return this.#bits;
  }

  /** @returns {number} Probes per value. */
  get hashes() {
    return this.#hashes;
  }

  /** @returns {number} Hash seed. */
  get seed() {
    return this.#seed;
  }

  /** @returns {number} How many values have been added. */
  get count() {
    return this.#count;
  }

  /**
   * Bit indices a value touches.
   * @param {string} value Value to probe.
   * @returns {number[]} One index per hash.
   * @throws {TypeError} When the value is not a string.
   */
  #probes(value) {
    if (typeof value !== 'string') throw new TypeError('value must be a string');
    const first = fnv1a(value, this.#seed);
    const second = (fnv1a(value, (this.#seed ^ SECOND_SEED) >>> 0) | 1) >>> 0;
    const out = [];
    for (let index = 0; index < this.#hashes; index += 1) {
      out.push(((first + Math.imul(index, second)) >>> 0) % this.#bits);
    }
    return out;
  }

  /**
   * Records a value.
   * @param {string} value Value to add.
   * @returns {BloomFilter} This filter.
   */
  add(value) {
    for (const index of this.#probes(value)) this.#set.set(index);
    this.#count += 1;
    return this;
  }

  /**
   * Reports whether a value may have been added.
   * @param {string} value Value to look up.
   * @returns {boolean} False when the value is certainly absent.
   */
  has(value) {
    for (const index of this.#probes(value)) {
      if (!this.#set.get(index)) return false;
    }
    return true;
  }

  /**
   * Fraction of bits currently set.
   * @returns {number} Value between zero and one.
   */
  fillRatio() {
    return this.#set.count() / this.#bits;
  }

  /**
   * Exposes the backing bit set so filters can be combined and written out.
   * @returns {BitSet} The backing bit set.
   */
  bitSet() {
    return this.#set;
  }

  /**
   * Merges another filter built with the same parameters.
   * @param {BloomFilter} other Filter to merge.
   * @returns {BloomFilter} New filter holding every bit of both.
   * @throws {TypeError} When the argument is not a filter.
   * @throws {RangeError} When the parameters differ.
   */
  union(other) {
    if (!(other instanceof BloomFilter)) throw new TypeError('argument must be a BloomFilter');
    if (other.bits !== this.#bits || other.hashes !== this.#hashes || other.seed !== this.#seed) {
      throw new RangeError('bloom filters must share their parameters');
    }
    const merged = new BloomFilter({ bits: this.#bits, hashes: this.#hashes, seed: this.#seed });
    const words = merged.bitSet().words();
    const mine = this.#set.words();
    const theirs = other.bitSet().words();
    for (let index = 0; index < words.length; index += 1) words[index] = mine[index] | theirs[index];
    merged.setCount(this.#count + other.count);
    return merged;
  }

  /**
   * Overrides the recorded number of added values.
   * @param {number} count New count; a non-negative safe integer.
   * @returns {void}
   * @throws {TypeError} When the count is not a non-negative safe integer.
   */
  setCount(count) {
    if (!Number.isSafeInteger(count) || count < 0) throw new TypeError('count must be a non-negative integer');
    this.#count = count;
  }

  /**
   * Writes the filter as bytes: a four-byte signature, the bit count, the
   * seed, the probe count, the number of added values, and then the bits.
   * @returns {Uint8Array} Serialized filter.
   */
  serialize() {
    const payload = this.#set.toBytes();
    const bytes = new Uint8Array(HEADER_BYTES + payload.length);
    bytes.set(MAGIC, 0);
    const view = new DataView(bytes.buffer);
    view.setUint32(4, this.#bits, true);
    view.setUint32(8, this.#seed, true);
    bytes[12] = this.#hashes;
    view.setUint32(13, this.#count, true);
    bytes.set(payload, HEADER_BYTES);
    return bytes;
  }

  /**
   * Rebuilds a filter written by `serialize`.
   * @param {Uint8Array} bytes Serialized filter.
   * @returns {BloomFilter} Restored filter.
   * @throws {TypeError} When the argument is not a Uint8Array.
   * @throws {Error} When the signature is missing.
   * @throws {RangeError} When the payload length disagrees with the header.
   */
  static deserialize(bytes) {
    if (!(bytes instanceof Uint8Array)) throw new TypeError('bytes must be a Uint8Array');
    if (bytes.length < HEADER_BYTES || MAGIC.some((byte, index) => bytes[index] !== byte)) {
      throw new Error('unrecognised bloom filter header');
    }
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    const bits = view.getUint32(4, true);
    const seed = view.getUint32(8, true);
    const hashes = bytes[12];
    const count = view.getUint32(13, true);
    if (bytes.length !== HEADER_BYTES + byteLength(bits)) {
      throw new RangeError('serialized length does not match the header');
    }
    const filter = new BloomFilter({ bits, hashes, seed });
    const restored = BitSet.fromBytes(bytes.slice(HEADER_BYTES), bits);
    filter.bitSet().words().set(restored.words());
    filter.setCount(count);
    return filter;
  }
}

